code='''def transform(grid):
    h,w=len(grid),len(grid[0])
    beams={}
    for r in range(h-2):
        for c in range(w-2):
            color=grid[r][c]
            if color and all(grid[i][j]==color for i in range(r,r+3) for j in range(c,c+3)):
                cr,cc=r+1,c+1
                for j in range(w): beams.setdefault((cr,j),set()).add(color)
                for i in range(h): beams.setdefault((i,cc),set()).add(color)
    out=[row[:] for row in grid]
    for (r,c),colors in beams.items(): out[r][c]=next(iter(colors)) if len(colors)==1 else 0
    return out
'''
